spec.section:
# config.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$defs": {
    "admission": {
      "additionalProperties": false,
      "properties": {
        "run_now_owner": {
          "enum": [
            "controller_local",
            "scheduler"
          ],
          "minLength": 1,
          "type": "string",
          "x-absence": "ERROR required_missing"
        },
        "scheduler_bump_fallback": {
          "type": "boolean",
          "x-absence": "ERROR required_missing"
        }
      },
      "required": [
        "run_now_owner",
        "scheduler_bump_fallback"
      ],
      "type": "object"
    },
    "agent": {
