      "additionalProperties": false,
      "description": "Central session-export archive (R31-016, D-017/D-018): namespace, checkpoint cadence, retention and the read scopes the harness config bounds. Records: contracts/DATA-MODEL.md §1.9/§1.10; queries VOL-B §5.10. Archive READ is granted per VOL-C §8.8 via GrantRecords owned by CHD31-06 — never by this block; there is no implicit read.",
      "properties": {
        "checkpoint_cadence_s": {
          "description": "Minimum seconds between checkpoint exports when checkpoint_interval is armed",
          "maximum": 9007199254740991,
          "minimum": 60,
          "type": "integer",
