          "pattern": "^[a-z][a-z0-9-]*$",
          "type": "string",
          "x-absence": "ERROR required_missing"
        },
        "read_scopes": {
          "description": "The scopes VP configuration BOUNDS (max grantable, VOL-C §8.8); actual reads still require a GrantRecord",
          "items": {
            "enum": [
              "own_history",
              "room_log",
              "cross_agent_archive"
            ],
            "minLength": 1,
            "type": "string"
          },
          "type": "array",
          "uniqueItems": true,
          "x-absence": "ERROR required_missing"
        },
        "retention_days": {
          "maximum": 9007199254740991,
          "minimum": 1,
          "type": "integer",
          "x-absence": "ERROR required_missing"
        }
      },
      "required": [
        "namespace",
        "export_trigger",
        "checkpoint_cadence_s",
        "retention_days",
        "read_scopes"
      ],
      "type": "object"
